(function(){
  const btn = document.getElementById('place');
  if (!btn) return {error: 'Button not found'};
  // Check if disabled
  const disabled = btn.disabled;
  // Check event listeners (if possible)
  let listeners = [];
  try {
    const evts = ['click', 'change', 'input'];
    evts.forEach(evt => {
      const el = btn;
      // Using getEventListeners if available (Chrome devtools only)
      if (typeof getEventListeners === 'function') {
        const ev = getEventListeners(el)[evt];
        if (ev) listeners.push({event: evt, count: ev.length});
      }
    });
  } catch(e) {}
  // Check for global functions related to placing order
  const funcs = Object.keys(window).filter(k => typeof window[k] === 'function' && k.toLowerCase().includes('order'));
  return {disabled, listeners, funcs};
})()

