  const funcs = Object.keys(window).filter(k => typeof window[k] === 'function' && k.toLowerCase().includes('order'));
  if(funcs.length > 0){
    try {
      // Try calling first such function
      window[funcs[0]]();
      return {calledFunction: funcs[0], success: true};
    } catch(e) {
      return {calledFunction: funcs[0], success: false, error: e.message};
    }
  }
  return {calledFunction: null, success: false};
})()

